private void ToggleClone(InputAction.CallbackContext context)
{
    if (_activeClone == null)
    {
        // Spawn new clone
        Vector3 pos = spawnPoint != null ? spawnPoint.position : transform.position;
        Quaternion rot = spawnPoint != null ? spawnPoint.rotation : transform.rotation;

        _activeClone = Instantiate(clonePrefab, pos, rot);

        // Optional: prevent controlling the clone if it has PlayerInput
        PlayerInput cloneInput = _activeClone.GetComponent<PlayerInput>();
        if (cloneInput != null) Destroy(cloneInput);
    }
    else
    {
        // Remove the existing clone
        Button button = FindObjectOfType<Button>();
        ButtonScript buttonScript = FindObjectOfType<ButtonScript>();
        if (button != null || buttonScript !=  null)
        {
            button.NotifyObjectRemoved();
            buttonScript.NotifyObjectRemoved();
        }
        Destroy(_activeClone);
        _activeClone = null;
    }
}

private void OnTriggerEnter(Collider other)
{
    if (other.CompareTag("Player") && inventory.HasDynamite == true)
    {
        inventory.HasDynamite = false;
        dynamite.SetActive(true);
        StartCoroutine(WachtEnVoerUit());
    }
}
