protected virtual void Update()
{
	if (currentState == State.Dying && prop == true)
	{
		Debug.Log("bin died :(");
		agent.isStopped = true;
		//this.enabled = false;
		Destroy(gameObject, 3f);
	}

	if (player == null || currentState == State.Dying || currentState == State.Death)
		return;

	float distanceToPlayer = Vector3.Distance(transform.position, player.position);

	switch (currentState)
	{
		case State.Idle:
			if (distanceToPlayer <= detectionRange)
			{
				currentState = (distanceToPlayer <= attackRange) ? State.Attack : State.WalkToPlayer;
				if(prop == true)
				{
					saw.SetActive(true);
				}
			}
			break;

		case State.WalkToPlayer:
			WalkToPlayer();
			if (distanceToPlayer <= attackRange)
				currentState = State.Attack;
			break;

		case State.Attack:
			Attack();
			if (distanceToPlayer > attackRange)
				currentState = State.WalkToPlayer;
			break;

		case State.Dying:
			Dying();
			break;
	}
}

